              "flex h-5 w-5 shrink-0 items-center justify-center " +
              STATUS_ICON_STYLE[status].boxClass
            }
            aria-hidden="true"
          >
            <StatusIcon
              className={"h-3 w-3 " + STATUS_ICON_STYLE[status].iconClass}
