                key={`${feature.id}/${task.id}`}
                task={task}
                feature={feature}
                onSelect={onSelectTask}
                onOpenTab={onOpenTaskTab}
                onOpenNewTab={onOpenTaskTabNewSession}
              />
            ))
          )}
        </div>
      )}
    </section>
  );
}

